import heapq

def busiest_links(trips, k):
    counts = {}
    for a, b in trips:
        name = a + '-' + b
        counts[name] = counts.get(name, 0) + 1
    best = heapq.nsmallest(k, ((-c, name) for name, c in counts.items()))
    return [name for _, name in best]

def busiest_links(trips, k):
    counts = {}
    for a, b in trips:
        name = a + '-' + b if a < b else b + '-' + a
        counts[name] = counts.get(name, 0) + 1
    ranked = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    return [name for name, _ in ranked[:k]]
